const agentReachIntegration = path.join(root, "integrations/agent-reach");
const shopifyIntegration = path.join(root, "integrations/shopify");

function replaceRequired(content, from, to, file) {
  const normalizedContent = content.replace(/\r\n/g, "\n");
  const normalizedTo = String(to).replace(/\r\n/g, "\n");
  if (normalizedContent.includes(normalizedTo)) return { content, changed: false };
  const variants = brandingAnchorVariants(from);
  for (const candidate of variants) {
    const normalizedCandidate = String(candidate).replace(/\r\n/g, "\n");
    if (normalizedContent.includes(normalizedCandidate)) {
      // Preserve the file's existing newline style when substituting.
      const usesCrlf = content.includes("\r\n");
      const fromInFile = usesCrlf ? normalizedCandidate.replace(/\n/g, "\r\n") : normalizedCandidate;
      const toInFile = usesCrlf ? normalizedTo.replace(/\n/g, "\r\n") : normalizedTo;
      if (!content.includes(fromInFile)) {
        // Fallback: replace via normalized round-trip for mixed newline files.
        return {
          content: normalizedContent.replace(normalizedCandidate, normalizedTo).replace(/\n/g, usesCrlf ? "\r\n" : "\n"),
          changed: true,
        };
      }
      return { content: content.replace(fromInFile, toInFile), changed: true };
    }
  }
  throw new Error(`Branding anchor not found in ${path.relative(root, file)}: ${variants[0]}`);
}

function localeKeyPrefix(from) {
  const sample = Array.isArray(from) ? from[0] : from;
  const match = String(sample).match(/^("[^"]+":)/);
  return match?.[1] ?? "";
}

function replaceRequiredOrExistingKey(content, from, to, file) {
  try {
    return replaceRequired(content, from, to, file);
  } catch (error) {
    const key = localeKeyPrefix(from) || localeKeyPrefix(to);
    // Pinned OpenWork may omit keys that only exist in the drifted local vendor.
    if (key) {
      return { content, changed: false };
    }
    throw error;
  }
}

function replaceAllRequired(content, from, to, file) {
  if (content.includes(to)) {
    return { content, changed: false };
  }
  const variants = brandingAnchorVariants(from);
  for (const candidate of variants) {
    if (!content.includes(candidate)) continue;
    const next = content.replaceAll(candidate, to);
    return { content: next, changed: next !== content };
  }
  throw new Error(`Branding anchor not found in ${path.relative(root, file)}: ${variants[0]}`);
}

async function patchFile(relativePath, replacements, { replaceAll = false, existingKeyOk = false } = {}) {
  const file = path.join(vendor, relativePath);
  let content = await readFile(file, "utf8");
  let changed = false;

  for (const [from, to] of replacements) {
    const result = replaceAll
      ? replaceAllRequired(content, from, to, file)
      : existingKeyOk
        ? replaceRequiredOrExistingKey(content, from, to, file)
        : replaceRequired(content, from, to, file);
    content = result.content;
    changed ||= result.changed;
  }

  if (changed) {
    await writeFile(file, content, "utf8");
    console.log("patched:", path.relative(root, file));
  } else {
    console.log("skip (already branded):", path.relative(root, file));
  }
}

function normalizeNewlines(text) {
  return String(text).replace(/\r\n/g, "\n");
}

function restoreNewlines(text, usesCrlf) {
  return usesCrlf ? text.replace(/\n/g, "\r\n") : text;
}

function insertAfterIfMissing(content, { marker, anchor, insert }, file) {
  const usesCrlf = content.includes("\r\n");
  const normalized = normalizeNewlines(content);
  if (normalized.includes(normalizeNewlines(marker))) return { content, changed: false };
  const normalizedAnchor = normalizeNewlines(anchor);
  const anchorPos = normalized.indexOf(normalizedAnchor);
  if (anchorPos < 0) {
    throw new Error(`OpenWork integration anchor not found in ${path.relative(root, file)}: ${anchor}`);
  }
  // If the anchor is a mid-line key prefix (common for i18n `"key":`), insert after that full line.
  let insertPos = anchorPos + normalizedAnchor.length;
  if (!normalizedAnchor.endsWith("\n")) {
    const eol = normalized.indexOf("\n", insertPos);
    insertPos = eol < 0 ? normalized.length : eol;
  }
  const insertText = normalizeNewlines(insert).replace(/\n+$/, "");
  const next = `${normalized.slice(0, insertPos)}\n${insertText}${normalized.slice(insertPos)}`;
  return { content: restoreNewlines(next, usesCrlf), changed: true };
}

function insertBeforeIfMissing(content, { marker, anchor, insert }, file) {
  const usesCrlf = content.includes("\r\n");
  const normalized = normalizeNewlines(content);
  if (normalized.includes(normalizeNewlines(marker))) return { content, changed: false };
  const normalizedAnchor = normalizeNewlines(anchor);
  if (!normalized.includes(normalizedAnchor)) {
    throw new Error(`OpenWork integration anchor not found in ${path.relative(root, file)}: ${anchor}`);
  }
  const next = normalized.replace(normalizedAnchor, `${normalizeNewlines(insert).replace(/\n+$/, "")}\n${normalizedAnchor}`);
  return { content: restoreNewlines(next, usesCrlf), changed: true };
}

function insertBeforeLastIfMissing(content, { marker, anchor, insert }, file) {
  const usesCrlf = content.includes("\r\n");
  const normalized = normalizeNewlines(content);
  if (normalized.includes(normalizeNewlines(marker))) return { content, changed: false };
  const normalizedAnchor = normalizeNewlines(anchor);
  const index = normalized.lastIndexOf(normalizedAnchor);
  if (index < 0) {
    throw new Error(`OpenWork integration anchor not found in ${path.relative(root, file)}: ${anchor}`);
  }
  const insertText = normalizeNewlines(insert).replace(/\n+$/, "");
  const next = `${normalized.slice(0, index)}${insertText}\n${normalized.slice(index)}`;
  return {
    content: restoreNewlines(next, usesCrlf),
    changed: true,
  };
}

function replaceAnyOrKeep(content, { variants, to, already = [] }, file) {
  const usesCrlf = content.includes("\r\n");
  const normalized = normalizeNewlines(content);
  const normalizedTo = normalizeNewlines(to);
  if (
    normalized.includes(normalizedTo)
    || already.some((marker) => normalized.includes(normalizeNewlines(marker)))
  ) {
    return { content, changed: false };
  }
  for (const from of brandingAnchorVariants(variants)) {
    const normalizedFrom = normalizeNewlines(from);
    if (!normalized.includes(normalizedFrom)) continue;
    const next = normalized.replace(normalizedFrom, normalizedTo);
    return { content: restoreNewlines(next, usesCrlf), changed: true };
  }
  return { content, changed: false };
}

function synchronizeDelimitedBlock(content, { start, end, replacement }, file) {
  const startIndex = content.indexOf(start);
  const endIndex = content.indexOf(end, startIndex + start.length);
  if (startIndex < 0 || endIndex < 0) {
    throw new Error(`OpenWork managed block anchor not found in ${path.relative(root, file)}: ${start} ... ${end}`);
  }
  const current = content.slice(startIndex, endIndex).trimEnd();
  const nextBlock = replacement.trimEnd();
  if (current === nextBlock) return { content, changed: false };
  return {
    content: `${content.slice(0, startIndex)}${nextBlock}\n\n${content.slice(endIndex)}`,
    changed: true,
  };
}

function extractDelimitedBlock(content, { start, end }, file) {
  const startIndex = content.indexOf(start);
  const endIndex = content.indexOf(end, startIndex + start.length);
  if (startIndex < 0 || endIndex < 0) {
    throw new Error(`OpenWork template block not found in ${path.relative(root, file)}: ${start} ... ${end}`);
  }
  return content.slice(startIndex, endIndex).trimEnd();
}

