const WODEAPP_PLATFORM_DEFAULTS = `## WodeApp Platform Defaults

Use the enabled typed tools and their schemas as the capability source. Runtime UI controls come from the live action registry.

## Memory

Two kinds:`;

function normalizeWodeAppPlatformDefaults(content, file) {
  if (content.includes("exposes capability instructions and tool schemas per turn")) {
    return { content, changed: false };
  }
  const existingDefaults = /## WodeApp Platform Defaults\n\n[\s\S]*?\n\n## Memory\n\nTwo kinds:/;
  if (existingDefaults.test(content)) {
    const next = content.replace(existingDefaults, WODEAPP_PLATFORM_DEFAULTS);
    return { content: next, changed: next !== content };
  }
  const memoryAnchor = "## Memory\n\nTwo kinds:";
  if (content.includes(memoryAnchor)) {
    return { content: content.replace(memoryAnchor, WODEAPP_PLATFORM_DEFAULTS), changed: true };
  }
  throw new Error(`OpenWork integration replacement anchors not found in ${path.relative(root, file)}: WodeApp Platform Defaults`);
}

const WODEAPP_CAPABILITIES_EXECUTION_MARKER = "Product/asset videos must carry material references";

const WODEAPP_DATA_VIDEO_KNOWLEDGE_RULE = `- Data-driven product video is an available route, not a keyword rule: choose it when the available product data and the task's batchability, determinism, editability, latency, or cost favor composition over generated motion.`;

const WODEAPP_PLATFORM_EXECUTION_BULLETS = `- Execute WodeApp workflows when the user asks; infer missing ratio/count/style from context.
${WODEAPP_CAPABILITY_ROUTING}
${WODEAPP_VIDEO_EXECUTION_RULE}
${WODEAPP_IMAGE_DELIVERY_RULE}
${WODEAPP_VIDEO_STORYBOARD_RULE}`;

function normalizeWodeAppCapabilitiesKnowledge(content) {
  const normalizedLegacy = content
    .split("\n")
    .map((line) => {
      if (line.startsWith("- Video: in WodeAppX chat")) return WODEAPP_VIDEO_EXECUTION_RULE;
      if (line.startsWith("- Video multi-item/storyboard:")) return WODEAPP_VIDEO_STORYBOARD_RULE;
      if (line.startsWith("- Data-driven product video:")) return WODEAPP_DATA_VIDEO_KNOWLEDGE_RULE;
      return line;
    })
    .join("\n");
  const legacyChanged = normalizedLegacy !== content;
  if (legacyChanged) content = normalizedLegacy;

  if (!content.includes("wodeapp_video_template_render")) {
    const videoDefaultsRule = "- Video defaults: preserve product/character identity from references; ask only for the most important missing choice among subject, ratio/platform, duration, or style. Return task IDs/URLs and poll when supported; pending video tasks are not failures.";
    const videoDefaultsIndex = content.indexOf(videoDefaultsRule);
    if (videoDefaultsIndex >= 0) {
      const next = content.slice(0, videoDefaultsIndex) + `${WODEAPP_DATA_VIDEO_KNOWLEDGE_RULE}\n` + content.slice(videoDefaultsIndex);
      return { content: next, changed: true };
    }
  }
  if (content.includes(WODEAPP_CAPABILITIES_EXECUTION_MARKER) && content.includes("does not require openwork_ui_list_actions first") && content.includes("wodeapp_video_template_render")) {
    return { content, changed: legacyChanged };
  }
  const executionBlockStart = "- Default execution rule: if the user clearly asks";
  const executionBlockEnd = "pending video tasks are not failures.";
  const startIdx = content.indexOf(executionBlockStart);
  if (startIdx < 0) return { content, changed: false };
  const endIdx = content.indexOf(executionBlockEnd, startIdx);
  if (endIdx < 0) return { content, changed: false };
  const endPos = endIdx + executionBlockEnd.length;
  const next = `${content.slice(0, startIdx)}${WODEAPP_PLATFORM_EXECUTION_BULLETS}${content.slice(endPos)}`;
  if (next === content) return { content, changed: false };
  return { content: next, changed: true };
}

async function patchOpenWorkFile(relativePath, transform) {
  const file = path.join(vendor, relativePath);
  const original = await readFile(file, "utf8");
  const next = transform(original, file);
  const content = typeof next === "string" ? next : next.content;
  const changed = typeof next === "string" ? next !== original : next.changed;

  if (changed) {
    await writeFile(file, content, "utf8");
    console.log("patched:", path.relative(root, file));
  } else {
    console.log("skip (already integrated):", path.relative(root, file));
  }
}

