async function syncBrowserControlIntegration() {
  const pluginSource = path.join(browserControlIntegration, "opencode-plugin");
  const pluginTarget = path.join(vendor, ".opencode", "plugins");
  await mkdir(pluginTarget, { recursive: true });
  for (const fileName of [
    "wodeappx-browser-control.ts",
    "wodeappx-browser-control-guidance.ts",
    "wodeappx-browser-control-runtime.mjs",
    "wodeappx-capabilities-bridge.ts",
    "wodeappx-hyperframes-runtime.mjs",
  ]) {
    const source = path.join(pluginSource, fileName);
    const target = path.join(pluginTarget, fileName);
    await cp(source, target, { force: true });
    console.log("synced:", path.relative(root, target));
  }

  // Always-on runtime plugin (Codex-like host): sidecar loads this via OPENCODE_CONFIG.
  const runtimePluginSource = path.join(pluginSource, "wodeappx-browser-control-server.ts");
  const runtimePluginTarget = path.join(vendor, "apps/server/src/opencode-plugins/wodeappx-browser-control.ts");
  const runtimeGuidanceSource = path.join(pluginSource, "wodeappx-browser-control-guidance.ts");
  const runtimeGuidanceTarget = path.join(vendor, "apps/server/src/opencode-plugins/wodeappx-browser-control-guidance.ts");
  const runtimeMjsTarget = path.join(vendor, "apps/server/src/opencode-plugins/wodeappx-browser-control-runtime.mjs");
  await mkdir(path.dirname(runtimePluginTarget), { recursive: true });
  await writeFile(runtimePluginTarget, await readFile(runtimePluginSource, "utf8"), "utf8");
  await cp(runtimeGuidanceSource, runtimeGuidanceTarget, { force: true });
  await cp(path.join(pluginSource, "wodeappx-browser-control-runtime.mjs"), runtimeMjsTarget, { force: true });
  console.log("synced:", path.relative(root, runtimePluginTarget));
  console.log("synced:", path.relative(root, runtimeGuidanceTarget));
  console.log("synced:", path.relative(root, runtimeMjsTarget));

  // Also keep fork sources aligned so openwork:patch from fork does not drop the plugin.
  const forkPluginTarget = path.join(openworkIntegration, "fork/apps/server/src/opencode-plugins/wodeappx-browser-control.ts");
  const forkGuidanceTarget = path.join(openworkIntegration, "fork/apps/server/src/opencode-plugins/wodeappx-browser-control-guidance.ts");
  const forkRuntimeTarget = path.join(openworkIntegration, "fork/apps/server/src/opencode-plugins/wodeappx-browser-control-runtime.mjs");
  await mkdir(path.dirname(forkPluginTarget), { recursive: true });
  await writeFile(forkPluginTarget, await readFile(runtimePluginSource, "utf8"), "utf8");
  await cp(runtimeGuidanceSource, forkGuidanceTarget, { force: true });
  await cp(path.join(pluginSource, "wodeappx-browser-control-runtime.mjs"), forkRuntimeTarget, { force: true });
  console.log("synced:", path.relative(root, forkPluginTarget));
  console.log("synced:", path.relative(root, forkGuidanceTarget));
  console.log("synced:", path.relative(root, forkRuntimeTarget));

  const skillSource = path.join(browserControlIntegration, "skills", "wodeappx-browser-control");
  const skillTarget = path.join(vendor, ".opencode", "skills", "wodeappx-browser-control");
  await mkdir(path.dirname(skillTarget), { recursive: true });
  await cp(skillSource, skillTarget, { recursive: true, force: true });
  console.log("synced:", path.relative(root, skillTarget));
}

async function syncWodeAppCloudElectronRuntime() {
  // Fork main.mjs always imports ./wodeapp-cloud/*.mjs for account binding.
  // OSS openwork:patch must ship those files; otherwise packaged Windows/macOS
  // installs crash with ERR_MODULE_NOT_FOUND for wodeapp-auth-ipc.mjs.
  const cloudElectronSource = path.join(root, "integrations/wodeapp-cloud/electron");
  const cloudElectronTarget = path.join(vendor, "apps/desktop/electron/wodeapp-cloud");
  const requiredFiles = [
    "wodeapp-auth-ipc.mjs",
    "wodeapp-local-assets-ipc.mjs",
    "wodeapp-provider.mjs",
    "wodeapp-node-request.mjs",
    "config-store.mjs",
    "login-bridge.mjs",
    "login-bridge-handoff.mjs",
    "login-bridge-close.mjs",
    "login-close-preload.cjs",
    "code-login.mjs",
    "embedded-bootstrap.mjs",
    "browser-session-auth.mjs",
    "wodeBrandedModels.js",
    "local-byok-import.mjs",
    "desktop-keys-store.mjs",
    "desktop-custom-vendors.mjs",
    "wodeapp-provider-capability-detect.mjs",
  ];
  for (const fileName of requiredFiles) {
    const sourceFile = path.join(cloudElectronSource, fileName);
    try {
      await readFile(sourceFile);
    } catch {
      throw new Error(`Missing required WodeApp electron runtime file: ${path.relative(root, sourceFile)}`);
    }
  }
  await rm(cloudElectronTarget, { recursive: true, force: true });
  await mkdir(path.dirname(cloudElectronTarget), { recursive: true });
  await cp(cloudElectronSource, cloudElectronTarget, { recursive: true });
  console.log("synced:", path.relative(root, cloudElectronTarget));
}

async function applyWodeAppPreloadAuthBridgePatch() {
  await patchOpenWorkFile("apps/desktop/electron/preload.mjs", (content, file) => {
    if (content.includes("wodeappAuth:") || content.includes('invoke("wodeapp:auth"')) {
      return { content, changed: false };
    }
    const insert = `  // WODEAPP_CLOUD_INTEGRATION
  wodeappAuth: {
    invoke(action, payload) {
      return ipcRenderer.invoke("wodeapp:auth", action, payload);
    },
  },
  wodeappAssets: {
    invoke(action, payload) {
      return ipcRenderer.invoke("wodeapp:assets", action, payload);
    },
  },
`;
    const anchors = [
      `  shell: {
    openExternal(url) {
      return ipcRenderer.invoke("openwork:shell:openExternal", url);
    },
    relaunch() {
      return ipcRenderer.invoke("openwork:shell:relaunch");
    },
  },
`,
      `  shell: {
    openExternal(url) {
      return ipcRenderer.invoke("openwork:shell:openExternal", url);
    },
  },
`,
    ];
    for (const anchor of anchors) {
      if (!content.includes(anchor)) continue;
      return { content: content.replace(anchor, `${anchor}${insert}`), changed: true };
    }
    throw new Error(`OpenWork integration anchor not found in ${path.relative(root, file)}: shell bridge for wodeappAuth`);
  });
}

async function applyDeepLinkStartupBacklogPatch() {
  await patchOpenWorkFile("apps/desktop/electron/preload.mjs", (content, file) => {
    let changed = false;

    let r = insertAfterIfMissing(content, {
      marker: "const pendingNativeDeepLinks = [];",
      anchor: 'const NATIVE_MENU_ZOOM_EVENT = "openwork:native-menu:zoom";',
      insert: "const pendingNativeDeepLinks = [];",
    }, file);
    content = r.content;
    changed ||= r.changed;

    r = insertAfterIfMissing(content, {
      marker: "  deepLinks: {",
      anchor: `  invokeDesktop(command, ...args) {
    return ipcRenderer.invoke("openwork:desktop", command, ...args);
  },`,
      insert: `  deepLinks: {
    takePending() {
      return pendingNativeDeepLinks.splice(0, pendingNativeDeepLinks.length);
    },
  },`,
    }, file);
    content = r.content;
    changed ||= r.changed;

    const legacyListener = `ipcRenderer.on(NATIVE_DEEP_LINK_EVENT, (_event, urls) => {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new CustomEvent(NATIVE_DEEP_LINK_EVENT, { detail: urls }));
});`;
    const bufferedListener = `ipcRenderer.on(NATIVE_DEEP_LINK_EVENT, (_event, urls) => {
  if (typeof window === "undefined") return;
  const normalized = Array.isArray(urls)
    ? urls.filter((url) => typeof url === "string" && url.trim())
    : [];
  pendingNativeDeepLinks.push(...normalized);
  window.dispatchEvent(new CustomEvent(NATIVE_DEEP_LINK_EVENT, { detail: normalized }));
});`;
    if (content.includes(legacyListener)) {
      content = content.replace(legacyListener, bufferedListener);
      changed = true;
    } else if (!content.includes(bufferedListener)) {
      throw new Error(`OpenWork integration anchor not found in ${path.relative(root, file)}: native deep-link listener`);
    }

    return { content, changed };
  });
}

async function applyElectronWorkerAsarUnpackPatch() {
  await patchOpenWorkFile("apps/desktop/electron-builder.yml", (content, file) => {
    let changed = false;
    const required = [
      "electron/local-tts-worker.mjs",
      "electron/wodeapp-cloud/wodeapp-node-request.mjs",
    ];
    if (!required.every((entry) => content.includes(entry))) {
      const anchor = `asarUnpack:
  - node_modules/.pnpm/@lydell+node-pty*/**
  - node_modules/node-pty/**`;
      if (!content.includes(anchor)) {
        throw new Error(`OpenWork integration anchor not found in ${path.relative(root, file)}: asarUnpack`);
      }
      content = content.replace(
        anchor,
        `${anchor}
  - electron/local-tts-worker.mjs
  - electron/wodeapp-cloud/wodeapp-node-request.mjs`,
      );
      changed = true;
    }

    const skillsBlock = `  - from: ../../.opencode/skills
    to: built-in-skills
    filter:
      - "**/*"`;
    const commandsBlock = `  - from: ../../.opencode/commands
    to: built-in-commands
    filter:
      - "自进化.md"
      - "evolve.md"`;
    const docsBlock = `  - from: ../../packages/docs
    to: openwork-docs
    filter:
      - "**/*.md"
      - "**/*.mdx"
      - "docs.json"`;
    const nativeHostBlock = `  - from: resources/native-hosts
    to: native-hosts
    filter:
      - "wodeappx-browser-native-host*"`;

    if (!content.includes("to: built-in-commands")) {
      if (!content.includes(skillsBlock)) {
        throw new Error(`OpenWork integration anchor not found in ${path.relative(root, file)}: built-in-commands`);
      }
      content = content.replace(skillsBlock, `${skillsBlock}
${commandsBlock}`);
      changed = true;
    }

    const skillsSection = content.includes("to: built-in-commands")
      ? `${skillsBlock}
${commandsBlock}`
      : skillsBlock;
    const duplicateSplit = `${skillsSection}
${nativeHostBlock}
${skillsSection}
${docsBlock}`;
    const split = `${skillsSection}
${nativeHostBlock}
${docsBlock}`;
    const canonicalAnchor = `${skillsSection}
${docsBlock}`;

    if (content.includes(duplicateSplit)) {
      content = content.replace(duplicateSplit, `${canonicalAnchor}
${nativeHostBlock}`);
      changed = true;
    } else if (content.includes(split)) {
      content = content.replace(split, `${canonicalAnchor}
${nativeHostBlock}`);
      changed = true;
    } else if (!content.includes("from: resources/native-hosts")) {
      if (!content.includes(canonicalAnchor)) {
        throw new Error(`OpenWork integration anchor not found in ${path.relative(root, file)}: native-host resources`);
      }
      content = content.replace(
        canonicalAnchor,
        `${canonicalAnchor}
${nativeHostBlock}`,
      );
      changed = true;
    }

    const selfEvolveBlock = `  - from: resources/self-evolve-source
    to: self-evolve-source
    filter:
      - "manifest.json"
      - "self-evolve-source.tar.zst"`;
    if (!content.includes("from: resources/self-evolve-source")) {
      const insertAfter = content.includes("from: resources/native-hosts")
        ? nativeHostBlock
        : canonicalAnchor;
      if (!content.includes(insertAfter)) {
        throw new Error(`OpenWork integration anchor not found in ${path.relative(root, file)}: self-evolve-source resources`);
      }
      content = content.replace(
        insertAfter,
        `${insertAfter}
${selfEvolveBlock}`,
      );
      changed = true;
    }

    const collapsed = collapseDuplicateBuiltInSkillsResources(content);
    if (collapsed !== content) {
      content = collapsed;
      changed = true;
    }

    return { content, changed };
  });
}

async function syncShopifyIntegration() {
  const pluginDir = path.join(shopifyIntegration, "opencode-plugin");
  const pluginSource = path.join(pluginDir, "wodeappx-shopify.ts");
  const helperSource = path.join(pluginDir, "shopify-feishu-sync.ts");
  const pluginTarget = path.join(vendor, ".opencode", "plugins", "wodeappx-shopify.ts");
  const helperTarget = path.join(vendor, ".opencode", "plugins", "shopify-feishu-sync.ts");
  const runtimePluginTarget = path.join(vendor, "apps/server/src/opencode-plugins/wodeappx-shopify.ts");
  const runtimeHelperTarget = path.join(vendor, "apps/server/src/opencode-plugins/shopify-feishu-sync.ts");
  const pluginContent = await readFile(pluginSource, "utf8");
  // Windows checkouts may use CRLF; normalize before the exact import rewrite.
  const runtimePluginContent = normalizeNewlines(pluginContent)
    .replace(
      /import\s+\{\s*tool\s*\}\s+from\s+"@opencode-ai\/plugin";\s*\n\s*import\s+\{([\s\S]*?)\}\s+from\s+"\.\/shopify-feishu-sync";\s*\n\s*const\s+z\s*=\s*tool\.schema;/,
      'import { z } from "zod";\nimport {$1} from "./shopify-feishu-sync.js";',
    )
    .replace(
      /import\s+\{\s*tool\s*\}\s+from\s+"@opencode-ai\/plugin";\s*\n\s*const\s+z\s*=\s*tool\.schema;/,
      'import { z } from "zod";',
    )
    .replace(
      /^    ([A-Za-z0-9_]+): tool\(\{([\s\S]*?)^    \}\),$/gm,
      (_match, name, body) => `    ${name}: {${body}    },`,
    );
  if (runtimePluginContent.includes("@opencode-ai/plugin") || /:\s*tool\(/.test(runtimePluginContent)) {
    throw new Error("Shopify runtime plugin conversion failed: still references @opencode-ai/plugin tool helpers");
  }
  await mkdir(path.dirname(pluginTarget), { recursive: true });
  await cp(pluginSource, pluginTarget, { force: true });
  await cp(helperSource, helperTarget, { force: true });
  await mkdir(path.dirname(runtimePluginTarget), { recursive: true });
  await writeFile(runtimePluginTarget, runtimePluginContent, "utf8");
  await cp(helperSource, runtimeHelperTarget, { force: true });
  console.log("synced:", path.relative(root, pluginTarget));
  console.log("synced:", path.relative(root, helperTarget));
  console.log("synced:", path.relative(root, runtimePluginTarget));
  console.log("synced:", path.relative(root, runtimeHelperTarget));
}

