async function removeWodeappMediaIntegration() {
  const cleanupTargets = [
    path.join(vendor, ".opencode/wodeapp-media-mcp-server.mjs"),
    path.join(vendor, ".opencode/wodeapp-media-runner.mjs"),
    path.join(vendor, ".opencode/wodeapp_media"),
    path.join(vendor, "apps/desktop/electron/wodeapp-media"),
    path.join(vendor, "apps/app/src/react-app/domains/wodeapp/wodeapp-media-client.ts"),
  ];
  for (const target of cleanupTargets) {
    try {
      await rm(target, { recursive: true, force: true });
      console.log("removed:", path.relative(root, target));
    } catch {
      // Best effort cleanup.
    }
  }

  const mainFile = path.join(vendor, "apps/desktop/electron/main.mjs");
  let content = await readFile(mainFile, "utf8");
  const before = content;
  content = content.replace(
    /\n\/\/ WODEAPP_MEDIA_INTEGRATION\nimport \{ handleWodeappMediaRun \} from "\.\/wodeapp-media\/wodeapp-media-bridge\.mjs";/,
    "",
  );
  content = content.replace(
    /\n  wodeappMediaRun: async \(_event, payload\) => handleWodeappMediaRun\(payload\),/,
    "",
  );
  if (content !== before) {
    await writeFile(mainFile, content, "utf8");
    console.log("patched:", path.relative(root, mainFile));
  }
}

function isRecord(value) {
  return Boolean(value && typeof value === "object" && !Array.isArray(value));
}

function normalizePluginList(value) {
  if (Array.isArray(value)) return value.filter((item) => typeof item === "string" && item.trim());
  if (typeof value === "string" && value.trim()) return [value.trim()];
  return [];
}

