async function applySupplyChainPolicy() {
  const target = path.join(vendor, "pnpm-workspace.yaml");
  let content = await readFile(target, "utf8");
  let changed = false;
  const minimumReleaseAgeExclusions = [
    "@isaacs/brace-expansion@5.0.1",
    "axios@1.16.0",
    "drizzle-orm@0.45.2",
    "electron@39.8.5",
    "fast-uri@3.1.2",
    "file-type@21.3.1",
    "form-data@4.0.6",
    "hono@4.12.25",
    "minimatch@8.0.6",
    "minimatch@10.2.5",
    "next@16.2.6",
    "nodemailer@9.0.1",
    "picomatch@2.3.2",
    "picomatch@4.0.4",
    "postcss@8.5.10",
    "react-router@7.15.1",
    "seroval@1.4.1",
    "tar@7.5.16",
    "ws@8.21.0",
  ];
  const ageAnchor = "minimumReleaseAgeExclude:\n";
  if (!content.includes(ageAnchor)) {
    throw new Error(`OpenWork integration anchor not found in ${path.relative(root, target)}: minimumReleaseAgeExclude`);
  }
  const missingAgeEntries = minimumReleaseAgeExclusions
    .filter((entry) => !content.includes(`  - '${entry}'`) && !content.includes(`  - "${entry}"`) && !content.includes(`  - ${entry}`))
    .map((entry) => `  - '${entry}'`);
  if (missingAgeEntries.length > 0) {
    content = content.replace(ageAnchor, `${ageAnchor}${missingAgeEntries.join("\n")}\n`);
    changed = true;
  }

  const start = "# WODEAPPX_SECURITY_OVERRIDES_START";
  const end = "# WODEAPPX_SECURITY_OVERRIDES_END";
  const policy = `${start}
overrides:
  '@isaacs/brace-expansion@<=5.0.0': 5.0.1
  'axios@<1.16.0': 1.16.0
  'drizzle-orm@<0.45.2': 0.45.2
  'fast-uri@<3.1.2': 3.1.2
  'file-type@<21.3.1': 21.3.1
  'form-data@>=4.0.0 <4.0.6': 4.0.6
  'hono@<4.12.25': 4.12.25
  'minimatch@>=3 <9': 8.0.6
  'minimatch@>=9 <10.2.5': 10.2.5
  'next@<16.2.6': 16.2.6
  'nodemailer@<9.0.1': 9.0.1
  'picomatch@>=2 <3': 2.3.2
  'picomatch@>=4 <4.0.4': 4.0.4
  'postcss@<8.5.10': 8.5.10
  'react-router@<7.15.1': 7.15.1
  'seroval@<1.4.1': 1.4.1
  'tar@<7.5.16': 7.5.16
  'ws@>=8 <8.21.0': 8.21.0`;
  if (content.includes(start) || content.includes(end)) {
    const next = synchronizeDelimitedBlock(content, { start, end, replacement: policy }, target);
    content = next.content;
    changed ||= next.changed;
  } else {
    if (/^overrides:/m.test(content)) {
      throw new Error(`OpenWork ${path.relative(root, target)} already defines unmanaged overrides`);
    }
    content = `${content.trimEnd()}\n\n${policy}\n${end}\n`;
    changed = true;
  }

  if (changed) {
    await writeFile(target, content, "utf8");
    console.log("patched:", path.relative(root, target));
  } else {
    console.log("skip (security policy current):", path.relative(root, target));
  }
}

async function applyOpenCodeBaseConfig() {
  const target = path.join(vendor, ".opencode/opencode.json");
  let existing = {};
  try {
    const parsed = JSON.parse(await readFile(target, "utf8"));
    if (isRecord(parsed)) existing = parsed;
  } catch {
    // Missing or invalid config is fine; write the managed base config below.
  }

  const plugin = normalizePluginList(existing.plugin);
  if (!plugin.includes("opencode-chrome-devtools@1.0.4")) {
    plugin.push("opencode-chrome-devtools@1.0.4");
  }
  if (!plugin.includes("opencode-scheduler@1.3.0") && !plugin.includes("opencode-scheduler")) {
    plugin.push("opencode-scheduler@1.3.0");
  }
  if (!plugin.includes(".opencode/plugins/wodeappx-shopify.ts")) {
    plugin.push(".opencode/plugins/wodeappx-shopify.ts");
  }
  if (!plugin.includes(".opencode/plugins/wodeappx-browser-control.ts")) {
    plugin.push(".opencode/plugins/wodeappx-browser-control.ts");
  }

  const provider = { ...(isRecord(existing.provider) ? existing.provider : {}) };
  delete provider.wode;

  const mcp = { ...(isRecord(existing.mcp) ? existing.mcp : {}) };
  delete mcp.wodeapp;
  delete mcp["wodeapp-media"];
  if (!isRecord(mcp["shopify-dev-mcp"])) {
    mcp["shopify-dev-mcp"] = {
      type: "local",
      command: ["npx", "-y", "@shopify/dev-mcp@latest"],
      enabled: true,
    };
  }

  const next = {
    ...existing,
    "$schema": typeof existing.$schema === "string"
      ? existing.$schema
      : "https://opencode.ai/config.json",
    permission: typeof existing.permission === "string" ? existing.permission : "allow",
    plugin,
  };

  if (Object.keys(provider).length > 0) {
    next.provider = provider;
  } else {
    delete next.provider;
  }

  if (Object.keys(mcp).length > 0) {
    next.mcp = mcp;
  } else {
    delete next.mcp;
  }

  if (LEGACY_WODE_MODEL_IDS.has(existing.model)) {
    delete next.model;
  }

  const nextContent = `${JSON.stringify(next, null, 2)}\n`;
  let current = "";
  try {
    current = await readFile(target, "utf8");
  } catch {
    // Missing target is fine; write it below.
  }
  if (current === nextContent) {
    console.log("skip (opencode config current):", path.relative(root, target));
  } else {
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, nextContent, "utf8");
    console.log("synced:", path.relative(root, target));
  }

  await applyOpenCodePackageConfig();
  await applyOpenCodeSidecarVersion();
}

