function opencodeAuthPath(config: ServerConfig): string {
  const storageDir = runtimeStorageDir(config);
  const xdgConfigHome = dirname(storageDir);
  const xdgRoot = dirname(xdgConfigHome);
  return join(xdgRoot, "data", "opencode", "auth.json");
}

async function authenticatedProviderIds(config?: ServerConfig): Promise<string[]> {
  if (!config) return [];
  try {
    const parsed = JSON.parse(await readFile(opencodeAuthPath(config), "utf8")) as unknown;
    if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) return [];
    return Object.entries(parsed)
      .filter(([id, value]) => id.trim() && typeof value === "object" && value !== null)
      .map(([id]) => id);
  } catch {
    return [];
  }
}

async function runtimeEnabledProviders(
  config: ServerConfig | undefined,
  runtimeConfig: Awaited<ReturnType<typeof readRuntimeOpencodeConfig>>,
): Promise<string[]> {
  return uniqueProviderIds([
    WODEAPP_PROVIDER_ID,
    ...runtimeEnabledProviderList(runtimeConfig),
    ...(await authenticatedProviderIds(config)),
  ]);
}

