/**
 * Settings / extensions user-facing copy: OpenWork/OpenCode → WodeAppX / local engine.
 * Keeps technical reserved prefixes OPENWORK_ / OPENCODE_ and deep-link protocols.
 */
function rewriteSettingsBrandValue(value, lang) {
  const protect = (s) =>
    s
      .replaceAll("OPENWORK_", "\u0000OW_\u0000")
      .replaceAll("OPENCODE_", "\u0000OC_\u0000")
      .replaceAll("openwork://", "\u0000OWPROTO\u0000")
      .replaceAll("openwork-dev://", "\u0000OWDEVPROTO\u0000")
      .replaceAll("openwork-dev-data", "\u0000OWDEVDATA\u0000");
  const restore = (s) =>
    s
      .replaceAll("\u0000OW_\u0000", "OPENWORK_")
      .replaceAll("\u0000OC_\u0000", "OPENCODE_")
      .replaceAll("\u0000OWPROTO\u0000", "openwork://")
      .replaceAll("\u0000OWDEVPROTO\u0000", "openwork-dev://")
      .replaceAll("\u0000OWDEVDATA\u0000", "openwork-dev-data");

  let s = protect(value);
  if (lang === "zh") {
    s = s.replaceAll("OpenWork/OpenCode", "WodeAppX / 本地引擎");
    s = s.replaceAll("OpenWork + OpenCode", "WodeAppX + 本地引擎");
    s = s.replaceAll("OpenWork", "WodeAppX");
    s = s.replaceAll("OpenCode", "本地引擎");
    s = s.replaceAll("本地的本地引擎", "本地的引擎");
    s = s.replaceAll("本地引擎 运行时", "本地引擎运行时");
    s = s.replaceAll("本地引擎 管理", "本地引擎管理");
  } else {
    s = s.replaceAll("OpenWork/OpenCode", "WodeAppX / the local engine");
    s = s.replaceAll("OpenWork + OpenCode", "WodeAppX + local engine");
    s = s.replaceAll("OpenWork", "WodeAppX");
    s = s.replaceAll("OpenCode engine", "local engine");
    s = s.replaceAll("OpenCode SDK link", "Local engine SDK link");
    s = s.replaceAll("OpenCode binary", "local engine binary");
    s = s.replaceAll("OpenCode process", "local engine process");
    s = s.replaceAll("OpenCode runtime", "local engine runtime");
    s = s.replaceAll("OpenCode lifecycle", "local engine lifecycle");
    s = s.replaceAll("OpenCode dev state", "local engine dev state");
    s = s.replaceAll("OpenCode:", "Local engine:");
    s = s.replaceAll("Restart OpenCode", "Restart local engine");
    s = s.replaceAll("by OpenCode", "by the local engine");
    s = s.replaceAll("affects OpenCode", "affects the local engine");
    s = s.replaceAll("how OpenCode runs", "how the local engine runs");
    s = s.replaceAll("time OpenCode is", "time the local engine is");
    s = s.replaceAll("OpenCode", "local engine");
  }
  return restore(s);
}

function rewriteSettingsBrandLocaleContent(content, lang) {
  let changed = false;
  let next = content.replace(
    /^(\s*"(?:settings|extensions)\.[^"]+":\s*")((?:\\.|[^"\\])*)(")/gm,
    (full, pre, value) => {
      const key = pre.match(/"((?:settings|extensions)\.[^"]+)":/)?.[1] ?? "";
      if (
        !key.startsWith("settings.") &&
        key !== "extensions.plugins_opencode_header" &&
        key !== "extensions.subtitle"
      ) {
        return full;
      }
      if (!/OpenWork|OpenCode/.test(value)) return full;
      const rewritten = rewriteSettingsBrandValue(value, lang);
      if (rewritten === value) return full;
      changed = true;
      return `${pre}${rewritten}"`;
    },
  );

  if (lang === "zh") {
    const headerFrom = "产品名称保留英文：OpenCode、OpenPackage、OpenWork";
    const headerTo = "产品名称：WodeAppX；保留技术前缀 OPENWORK_ / OPENCODE_";
    if (next.includes(headerFrom)) {
      next = next.replace(headerFrom, headerTo);
      changed = true;
    }
  }

  if (lang === "en") {
    for (const [from, to] of [
      ['"settings.opencode_engine_label": "local engine"', '"settings.opencode_engine_label": "Local engine"'],
      ['"settings.opencode_engine_sidecar": "local engine"', '"settings.opencode_engine_sidecar": "Local engine"'],
      ['"settings.opencode_section_label": "local engine"', '"settings.opencode_section_label": "Local engine"'],
      ['"settings.opencode_cache": "Local cache"', '"settings.opencode_cache": "Local engine cache"'],
      ['"settings.opencode_cache": "local engine cache"', '"settings.opencode_cache": "Local engine cache"'],
      ['"settings.debug_opencode_version": "local engine: {version}"', '"settings.debug_opencode_version": "Local engine: {version}"'],
    ]) {
      if (next.includes(from)) {
        next = next.replace(from, to);
        changed = true;
      }
    }
  }

  return { content: next, changed };
}

function upsertLocaleEntries(content, entries) {
  let next = content.replace(/",,/g, '",');
  let changed = next !== content;
  for (const [key, value] of Object.entries(entries ?? {})) {
    const escapedKey = key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const lineRe = new RegExp(`^(\\s*)"${escapedKey}":\\s*"(?:\\\\.|[^"\\\\])*"\\s*,?\\s*$`, "m");
    const line = `  ${JSON.stringify(key)}: ${JSON.stringify(value)},`;
    if (lineRe.test(next)) {
      const updated = next.replace(
        lineRe,
        (_m, indent) => `${indent}${JSON.stringify(key)}: ${JSON.stringify(value)},`,
      );
      if (updated !== next) {
        next = updated;
        changed = true;
      }
      continue;
    }
    const close = next.lastIndexOf("\n} as const;");
    if (close < 0) {
      throw new Error("locale file is missing closing `} as const;`");
    }
    next = `${next.slice(0, close)}\n${line}${next.slice(close)}`;
    changed = true;
  }
  return { content: next, changed };
}

async function applyExcludeVendoredPageFlipFromTypecheck() {
  const relativePath = "apps/app/tsconfig.json";
  const file = path.join(vendor, relativePath);
  let content = await readFile(file, "utf8");
  const excludeNeedles = [
    "src/react-app/domains/wodeapp/vendor/page-flip/**",
    "src/react-app/**/*.test.ts",
    "src/react-app/**/*.test.tsx",
  ];
  let parsed;
  try {
    parsed = JSON.parse(content);
  } catch (error) {
    throw new Error(`Failed to parse ${relativePath}: ${error instanceof Error ? error.message : error}`);
  }
  const exclude = Array.isArray(parsed.exclude) ? [...parsed.exclude] : [];
  let changed = false;
  for (const needle of excludeNeedles) {
    if (!exclude.includes(needle)) {
      exclude.push(needle);
      changed = true;
    }
  }
  if (!changed) {
    console.log("skip (already integrated):", path.relative(root, file));
    return;
  }
  parsed.exclude = exclude;
  await writeFile(file, `${JSON.stringify(parsed, null, 2)}\n`, "utf8");
  console.log("patched:", path.relative(root, file));
}

