/** User-facing ApiError/Error strings still said "OpenCode"; map to "Local engine" (matches settings brand). Keep opencode_* codes. */
async function applyEngineBrandApiErrorPatch() {
  const replacements = [
    ["OpenCode returned invalid", "Local engine returned invalid"],
    ["OpenCode rejected the session read request", "Local engine rejected the session read request"],
    ["OpenCode returned an empty response", "Local engine returned an empty response"],
    ["OpenCode request failed", "Local engine request failed"],
    ["OpenCode base URL is missing for this workspace", "Local engine base URL is missing for this workspace"],
    ["OpenCode session did not return an id", "Local engine session did not return an id"],
    ["OpenCode base URL is invalid", "Local engine base URL is invalid"],
    [
      "OpenCode engine is not reachable; a full engine restart is required",
      "Local engine is not reachable; a full engine restart is required",
    ],
    ["OpenCode engine is not reachable", "Local engine is not reachable"],
    ["OpenCode run status query failed", "Local engine run status query failed"],
    ["OpenCode reload failed", "Local engine reload failed"],
    ["OpenCode config", "Local engine config"],
    [
      "OpenCode session.messages returned no message array",
      "Local engine session.messages returned no message array",
    ],
    ["OpenCode live tool registry is unavailable", "Local engine live tool registry is unavailable"],
    ["OpenCode database not found", "Local engine database not found"],
    ["OpenCode session not found", "Local engine session not found"],
    ["OpenCode server exited with code", "Local engine server exited with code"],
  ];

  const files = [
    "apps/server/src/session-read-model.ts",
    "apps/server/src/session-read-model.e2e.test.ts",
    "apps/server/src/routes/sessions.ts",
    "apps/server/src/server.ts",
    "apps/server/src/engine/opencode-v1-adapter.ts",
    "apps/server/src/opencode-plugins/openwork-extensions-preview.ts",
    "apps/server/src/opencode-plugins/wodeapp-tool-discovery.ts",
    "apps/server/src/workspace-import-preview.ts",
    "apps/server/src/opencode-db.ts",
    "apps/server/src/managed-opencode.ts",
  ];

  for (const relativePath of files) {
    const file = path.join(vendor, relativePath);
    let content;
    try {
      content = await readFile(file, "utf8");
    } catch (error) {
      if (error && error.code === "ENOENT") {
        console.log("skip (missing):", path.relative(root, file));
        continue;
      }
      throw error;
    }
    let next = content;
    for (const [from, to] of replacements) {
      next = next.split(from).join(to);
    }
    if (next !== content) {
      await writeFile(file, next, "utf8");
      console.log("patched:", path.relative(root, file));
    } else {
      console.log("skip (already branded):", path.relative(root, file));
    }
  }
}

